ALTER TABLE public.rendezvous DROP CONSTRAINT IF EXISTS rendezvous_nature_dossier_check;
ALTER TABLE public.rendezvous ADD CONSTRAINT rendezvous_nature_dossier_check CHECK (nature_dossier IS NULL OR nature_dossier IN ('installation', 'remplacement', 'maintenance', 'mise_en_service', 'depose', 'cablage', 'depannage', 'controle', 'autre'));